-- Additive migration; enables no writes or clients. Preserve OAuth identity and reader.
begin;
create schema hs_mcp_private;
revoke all on schema hs_mcp_private from public, anon, authenticated;
alter default privileges in schema hs_mcp_private revoke execute on functions from public;

alter table public.hs_mcp_clients
  add column write_enabled boolean not null default false,
  add column write_consent_version text,
  add column write_consented_at timestamptz;
create table hs_mcp_private.control(id boolean primary key default true check(id), writes_enabled boolean not null default false);
insert into hs_mcp_private.control default values;
create table hs_mcp_private.receipts(
  request_id uuid primary key, actor uuid not null references auth.users(id), client_id text not null,
  command jsonb not null, result jsonb not null, created_at timestamptz not null default now()
);
create table hs_mcp_private.activity(
  request_id uuid primary key references hs_mcp_private.receipts(request_id) deferrable initially deferred,
  actor uuid not null references auth.users(id), client_id text not null, operation text not null,
  record_id uuid, revision integer not null, created_at timestamptz not null default now()
);
alter table hs_mcp_private.control enable row level security;
alter table hs_mcp_private.receipts enable row level security;
alter table hs_mcp_private.activity enable row level security;
revoke all on all tables in schema hs_mcp_private from public, anon, authenticated;

-- Directory revisions must also advance on ordinary owner-dashboard upserts.
alter table public.hs_musicians add column revision integer not null default 1 check(revision>0);
alter table public.hs_pieces add column revision integer not null default 1 check(revision>0);
create function hs_mcp_private.directory_revision() returns trigger
language plpgsql set search_path='' as $$
begin
  new.revision := case when tg_op='INSERT' then 1 else old.revision+1 end;
  return new;
end $$;
create trigger hs_musician_revision before insert or update on public.hs_musicians
for each row execute function hs_mcp_private.directory_revision();
create trigger hs_piece_revision before insert or update on public.hs_pieces
for each row execute function hs_mcp_private.directory_revision();

create function public.hs_mcp_can_write() returns boolean
language sql stable security definer set search_path='' as $$
  select coalesce(public.hs_mcp_can_read(),false)
    and exists(select 1 from hs_mcp_private.control where writes_enabled)
    and exists(select 1 from public.hs_mcp_clients c where c.client_id=auth.jwt()->>'client_id'
      and c.user_id=auth.uid() and c.enabled and c.write_enabled
      and c.write_consent_version='operational-v1' and c.write_consented_at is not null);
$$;
revoke all on function public.hs_mcp_can_write() from public, anon;
grant execute on function public.hs_mcp_can_write() to authenticated;

create function hs_mcp_private.owner_session() returns boolean
language sql stable set search_path='' as $$
  select public.hs_is_owner() and auth.jwt()->>'role'='authenticated'
    and coalesce(auth.jwt()->>'is_anonymous','false')='false'
    and exists(select 1 from auth.sessions s where s.id::text=auth.jwt()->>'session_id'
      and s.user_id=auth.uid() and (s.not_after is null or s.not_after>now()));
$$;
create function public.hs_mcp_owner_clients() returns jsonb
language plpgsql stable security definer set search_path='' as $$
begin
  if not coalesce(hs_mcp_private.owner_session(),false) then raise exception 'Owner session required' using errcode='42501'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('clientId',client_id,'label',label,'resource',resource_url,
    'readEnabled',enabled,'writeEnabled',write_enabled,'consented',write_consent_version='operational-v1' and write_consented_at is not null))
    from public.hs_mcp_clients where user_id=auth.uid()),'[]'::jsonb);
end $$;
create function public.hs_mcp_consent_write(p_client_id text,p_allow boolean) returns void
language plpgsql security definer set search_path='' as $$
begin
  if not coalesce(hs_mcp_private.owner_session(),false) then raise exception 'Owner session required' using errcode='42501'; end if;
  if p_allow is null then raise exception 'Consent choice required' using errcode='22023'; end if;
  update public.hs_mcp_clients set write_consent_version=case when p_allow then 'operational-v1' end,
    write_consented_at=case when p_allow then now() end
    where client_id=p_client_id and user_id=auth.uid() and enabled;
  if not found then raise exception 'Registered owner client required' using errcode='42501'; end if;
end $$;
revoke all on function public.hs_mcp_owner_clients(),public.hs_mcp_consent_write(text,boolean) from public,anon;
grant execute on function public.hs_mcp_owner_clients(),public.hs_mcp_consent_write(text,boolean) to authenticated;

