-- Closed JSON-schema subset. Never coerce a primitive with ->> before validation.
create function hs_mcp_private.valid(v jsonb,s jsonb) returns boolean
language plpgsql immutable set search_path='' as $$
declare k text; child jsonb; typ text; str text; num numeric;
begin
  if v is null or v='null'::jsonb or s is null then return false; end if;
  if s ? 'anyOf' then
    for child in select value from jsonb_array_elements(s->'anyOf') loop
      if hs_mcp_private.valid(v,child) then return true; end if;
    end loop;
    return false;
  end if;
  typ:=s->>'type';
  if typ='object' then
    if jsonb_typeof(v)<>'object' then return false; end if;
    for k in select jsonb_array_elements_text(coalesce(s->'required','[]')) loop
      if not v ? k then return false; end if;
    end loop;
    for k,child in select * from jsonb_each(v) loop
      if not (s->'properties') ? k or not hs_mcp_private.valid(child,s->'properties'->k) then return false; end if;
    end loop;
  elsif typ='string' then
    if jsonb_typeof(v)<>'string' then return false; end if;
    str:=v#>>'{}';
    if length(str)>coalesce((s->>'maxLength')::int,10000) or length(trim(str))<coalesce((s->>'minLength')::int,0) then return false; end if;
    if s ? 'pattern' and str !~ (s->>'pattern') then return false; end if;
    if s->>'format'='date' and (str !~ '^\d{4}-\d{2}-\d{2}$' or to_char(str::date,'YYYY-MM-DD')<>str) then return false; end if;
    if s->>'format'='uri' and str !~ '^https?://[^[:space:]/?#]+([/?#][^[:space:]]*)?$' then return false; end if;
  elsif typ in ('integer','number') then
    if jsonb_typeof(v)<>'number' then return false; end if;
    num:=(v#>>'{}')::numeric;
    if typ='integer' and num<>trunc(num) then return false; end if;
    if s ? 'minimum' and num<(s->>'minimum')::numeric or s ? 'maximum' and num>(s->>'maximum')::numeric then return false; end if;
  elsif typ='boolean' then
    if jsonb_typeof(v)<>'boolean' then return false; end if;
  else return false;
  end if;
  if s ? 'enum' and not (s->'enum') @> jsonb_build_array(v) then return false; end if;
  if s ? 'const' and v<>s->'const' then return false; end if;
  return true;
exception when invalid_datetime_format or datetime_field_overflow then return false;
end $$;

-- Sole delegated mutation entry. All guards, revision, mutation, attribution and
-- receipt share the caller's transaction. Helpers have no delegated privileges.
create function public.hs_mcp_mutate(p_command jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  op text; rid uuid; eid uuid; expected integer; d jsonb; contract jsonb;
  receipt hs_mcp_private.receipts; e public.hs_events; old_record jsonb; merged jsonb;
  result jsonb; result_revision integer; today text:=to_char(now() at time zone 'Australia/Sydney','YYYY-MM-DD');
  grp text; val jsonb; k text; tbl text; cols text; updates text; count_rows int; limit_rows int; child_id uuid;
begin
  -- Check even before receipt lookup: revocation also denies retries.
  if not coalesce(public.hs_mcp_can_write(),false) then raise exception 'MCP write access denied' using errcode='42501'; end if;
  if p_command is null or jsonb_typeof(p_command)<>'object' or octet_length(p_command::text)>32768
    or jsonb_typeof(p_command->'operation') is distinct from 'string' then
    raise exception 'Invalid command' using errcode='22023';
  end if;
  op:=p_command->>'operation'; contract:=hs_mcp_private.command_contract()->op;
  if not hs_mcp_private.valid(p_command-'operation',contract) then raise exception 'Invalid command shape' using errcode='22023'; end if;
  rid:=(p_command->>'requestId')::uuid; expected:=(p_command->>'expectedRevision')::int;
  eid:=(p_command->>'id')::uuid; d:=p_command->'data';
  -- Serialize identical IDs including concurrent retries; no receipt is created on rejection.
  perform pg_advisory_xact_lock(hashtextextended(rid::text,0));
  -- Serialize grant/session revocation with in-flight mutations. A revocation
  -- committed while this request was waiting must be observed before effects
  -- or receipt replay; a revocation waiting on us takes effect after our commit.
  perform 1 from hs_mcp_private.control where id for share;
  perform 1 from public.hs_mcp_clients where client_id=auth.jwt()->>'client_id' for share;
  perform 1 from public.hs_owners where user_id=auth.uid() for share;
  perform 1 from auth.sessions where id::text=auth.jwt()->>'session_id' and user_id=auth.uid() for share;
  if not coalesce(public.hs_mcp_can_write(),false) then raise exception 'MCP write access denied' using errcode='42501'; end if;
  select * into receipt from hs_mcp_private.receipts where request_id=rid;
  if found then
    if receipt.actor<>auth.uid() or receipt.client_id<>auth.jwt()->>'client_id' or receipt.command<>p_command then
      raise exception 'Request ID already bound to another command' using errcode='22023';
    end if;
    return receipt.result;
  end if;
  if d='{}'::jsonb then raise exception 'Empty update' using errcode='22023'; end if;

  if op in ('upsert_musician','upsert_piece') then
    tbl:=case op when 'upsert_musician' then 'hs_musicians' else 'hs_pieces' end;
    execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tbl) into old_record using eid;
    if expected=0 and old_record is not null or expected>0 and (old_record is null or (old_record->>'revision')::int<>expected) then
      raise exception 'Directory revision changed' using errcode='40001';
    end if;
    merged:=coalesce(old_record,'{}'::jsonb)||d||jsonb_build_object('id',eid,'revision',1);
    if op='upsert_piece' then merged:=jsonb_build_object('genre','','weddingSuitable','Unreviewed')||merged; end if;
    select string_agg(format('%I',a.attname),','),string_agg(format('%1$I=excluded.%1$I',a.attname),',') into cols,updates
      from pg_attribute a where a.attrelid=format('public.%I',tbl)::regclass and a.attnum>0 and not a.attisdropped and a.attname not in ('id','revision');
    execute format('insert into public.%1$I as t select * from jsonb_populate_record(null::public.%1$I,$1) on conflict(id) do update set %2$s returning to_jsonb(t)',tbl,updates)
      into result using merged;
    result_revision:=(result->>'revision')::int;
  elsif op='update_workflow_settings' then
    select to_jsonb(s)-'id' into old_record from public.hs_settings s where id=1 for update;
    if (old_record->>'revision')::int<>expected then raise exception 'Settings revision changed' using errcode='40001'; end if;
    merged:=old_record||d;
    if (merged->>'internalWeeks')::int<(merged->>'finalWeeks')::int or (merged->>'finalWeeks')::int<(merged->>'finalCheckWeeks')::int then
      raise exception 'Invalid workflow timing order' using errcode='22023';
    end if;
    -- Existing invoker settings RPC safely runs only inside this guarded definer.
    result:=public.hs_save_settings(merged); result_revision:=(result->>'revision')::int;
  else
    select * into e from public.hs_events where id=eid for update;
    if op='create_event' then
      if expected<>0 or e.id is not null then raise exception 'Event already exists or creation revision invalid' using errcode='40001'; end if;
      insert into public.hs_events(id,name,"createdDate","updatedBy") values(eid,d->>'name',today,auth.uid()) returning * into e;
      insert into public.hs_details("eventId",key,state) select eid,unnest(array['timing','venueSetup','wetWeather','onDayContact','repertoireBrief','rehearsal','logistics','runSheet']),'Unknown';
      insert into public.hs_finance values(eid,0,0,0,0,400,false,400,'',0,'','',false,0);
    else
      if e.id is null or e.revision<>expected then raise exception 'Event revision changed' using errcode='40001'; end if;
      if e.archived or e."deletedAt"<>'' then raise exception 'Archived, Lost or trashed events cannot be edited by MCP' using errcode='22023'; end if;
    end if;
    if op in ('create_event','update_event') then
      if d ? 'milestones' then
        for k,val in select * from jsonb_each(d->'milestones') loop
          if val#>>'{}'>today then raise exception 'Recorded milestone cannot be in future' using errcode='22023'; end if;
        end loop;
      end if;
      if d ? 'details' then
        for grp,val in select * from jsonb_each(d->'details') loop
          if val->>'state'='Deferred' and val->>'dueDate'='' and val->>'trigger'='' then raise exception 'Deferral requires date or trigger' using errcode='22023'; end if;
          update public.hs_details set state=val->>'state',value=val->>'value',"dueDate"=val->>'dueDate',trigger=val->>'trigger' where "eventId"=eid and key=grp;
        end loop;
      end if;
      merged:=to_jsonb(e)|| (d-'details'-'operational'-'milestones');
      merged:=merged||jsonb_build_object('milestones',e.milestones||coalesce(d->'milestones','{}'));
      old_record:=e.operational;
      for grp,val in select * from jsonb_each(coalesce(d->'operational','{}')) loop
        old_record:=jsonb_set(old_record,array[grp],coalesce(old_record->grp,'{}')||val);
      end loop;
      merged:=merged||jsonb_build_object('operational',old_record);
      e:=jsonb_populate_record(null::public.hs_events,merged);
      update public.hs_events set name=e.name,"eventDate"=e."eventDate","eventType"=e."eventType",ensemble=e.ensemble,
        "durationMinutes"=e."durationMinutes",area=e.area,address=e.address,source=e.source,notes=e.notes,
        milestones=e.milestones,operational=e.operational where id=eid;
    else
      tbl:=case op when 'upsert_event_contact' then 'hs_contacts' when 'upsert_event_task' then 'hs_tasks'
        when 'record_event_communication' then 'hs_communications' when 'upsert_event_musician' then 'hs_event_musicians'
        when 'upsert_event_repertoire' then 'hs_event_repertoire' end;
      if tbl is null then raise exception 'Unsupported operation' using errcode='22023'; end if;
      child_id:=(d->>'id')::uuid;
      execute format('select to_jsonb(t) from public.%I t where id=$1 for update',tbl) into old_record using child_id;
      if old_record is not null and old_record->>'eventId'<>eid::text then raise exception 'Child belongs to another event' using errcode='22023'; end if;
      limit_rows:=case tbl when 'hs_contacts' then 40 when 'hs_event_musicians' then 30 when 'hs_event_repertoire' then 150 else 500 end;
      execute format('select count(*) from public.%I where "eventId"=$1',tbl) into count_rows using eid;
      if old_record is null and count_rows>=limit_rows then raise exception 'Event collection limit exceeded' using errcode='22023'; end if;
      merged:=jsonb_build_object('sortOrder',count_rows)||coalesce(old_record,'{}')||d||jsonb_build_object('eventId',eid);
      if tbl='hs_tasks' then
        if (d->>'done')::boolean<>(d->>'completedAt'<>'') or d->>'completedAt'>today then raise exception 'Invalid task completion' using errcode='22023'; end if;
      elsif tbl='hs_communications' and d->>'date'>today then raise exception 'Communication cannot be in future' using errcode='22023';
      elsif tbl='hs_event_musicians' then
        merged:=jsonb_build_object('fee',0,'paid',false)||merged||jsonb_build_object('musicianId',nullif(d->>'musicianId',''));
      elsif tbl='hs_event_repertoire' then
        merged:=merged||jsonb_build_object('pieceId',nullif(d->>'pieceId',''));
      end if;
      select string_agg(format('%1$I=excluded.%1$I',a.attname),',') into updates
        from pg_attribute a where a.attrelid=format('public.%I',tbl)::regclass and a.attnum>0 and not a.attisdropped and a.attname not in ('id','eventId','fee','paid','sortOrder');
      execute format('insert into public.%1$I select * from jsonb_populate_record(null::public.%1$I,$1) on conflict(id) do update set %2$s',tbl,updates) using merged;
    end if;
    update public.hs_events set revision=case when op='create_event' then revision else revision+1 end,"updatedAt"=now(),"updatedBy"=auth.uid()
      where id=eid returning revision into result_revision;
    insert into public.hs_audit(event_id,revision) values(eid,result_revision);
    result:=public.hs_get_event(eid);
  end if;
  result:=jsonb_build_object('requestId',rid,'operation',op,'record',result,'revision',result_revision);
  insert into hs_mcp_private.receipts(request_id,actor,client_id,command,result) values(rid,auth.uid(),auth.jwt()->>'client_id',p_command,result);
  insert into hs_mcp_private.activity(request_id,actor,client_id,operation,record_id,revision) values(rid,auth.uid(),auth.jwt()->>'client_id',op,eid,result_revision);
  return result;
end $$;
revoke all on function public.hs_mcp_mutate(jsonb) from public,anon;
grant execute on function public.hs_mcp_mutate(jsonb) to authenticated;
revoke all on all functions in schema hs_mcp_private from public,anon,authenticated;
commit;
